mapper.insert:
insert into ETR_CASH_POSITION (PORTFOLIO_ID, ACCT_ID, HODING_TYPE, CDATE, CCY, AMOUNT, CHL_FINPROD_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT targetTable.PORTFOLIO_ID, targetTable.ACCT_ID, HODING_TYPE, #{batchDate,jdbcType=DATE}, targetTable.CCY, SUM(targetTable.AMOUNT), targetTable.CHL_FINPROD_ID, 'system', null, sysdate, 'system', sysdate FROM ( SELECT PORTFOLIO_ID, ACCT_ID, CCY, AMOUNT, CHL_FINPROD_ID, HODING_TYPE FROM ETR_CASH_POSITION WHERE HODING_TYPE IN (#{POSITION_TYPE_E01,jdbcType=VARCHAR},#{POSITION_TYPE_E02,jdbcType=VARCHAR}) and CDATE = #{lastDate,jdbcType=DATE}
and (
)
union all SELECT PORTFOLIO_ID, ACCT_ID, CCY, SUM(AMOUNT) as AMOUNT, CHL_FINPROD_ID, HODING_TYPE FROM ETR_CASH_POSITION_FLOW WHERE HODING_TYPE IN (#{POSITION_TYPE_E01,jdbcType=VARCHAR},#{POSITION_TYPE_E02,jdbcType=VARCHAR}) and CDATE = #{batchDate,jdbcType=DATE}
and (
)
GROUP BY PORTFOLIO_ID, ACCT_ID, CCY, CHL_FINPROD_ID, HODING_TYPE ) targetTable group by targetTable.PORTFOLIO_ID, targetTable.ACCT_ID, targetTable.CCY, targetTable.CHL_FINPROD_ID, targetTable.HODING_TYPE

mapper.select:
SELECT EE.ENTRUST_ID, EE.PORTFOLIO_ID, EE.FINPROD_ID, EE.FINPROD_TYPE2, EE.TRADE_MARKET, EE.TRADE_PLAT, EE.TRADE_MARKET_MODE, EE.PS, EE.CCY, EE.INV_AIM, EE.COUNTER_ID, EE.IS_OUT_TRADE, EE.COUNTER_TRADER, EE.CONTACT_INFO, EE.ENTRUST_DATE, EE.VDATE EEVDATE, EE.MDATE EEMDATE, EE.ENTRUST_AMT, EE.ENTRUST_NUM, EE.AVAILABLE_NUM, EE.PRO_AVAILABLE_CASH, EE.ACC_AVAILABLE_CASH, EE.ENTRUST_STATUS, EE.PRICE, EE.IS_ACCURATE, EE.INV_MANAGER_ID, EE.CALENDAR_ID, EE.REMARK, EE.PRICE_MODEL, EE.CHL_ID, EEA.SETTLE_SPREED, EEA.EXER_YIELD, EEA.MATURE_YIELD, EEA.VDATE, EEA.MDATE, EEA.TERM_DAYS, EEA.TERM_DAYS2, EEA.TERM_TYPE, EEA.PAY_FREQ, EEA.FIRST_CAL_DATE, EEA.ASSET_TYPE, EEA.ASSET_TYPE1, EEA.BUSI_PS, EEA.CASH_USEDATE, EEA.SEC_ACCT_ID, EEA.FIRST_UNIT_CPRICE, EEA.FIRST_UNIT_CPRICE2, EEA.EXCHANGE_PLEDGE, EEA.EXC_DEAL_TYPE, EEA.CUR_PAIR, EEA.COR_CCY, EEA.EXP_COR_AMT, EEA.COR_CUR_POS, EEA.IS_DIF_SQU, EEA.DEAL_CUR_ACCT, EEA.COR_CUR_ACCT, EEA.CNY_ACCT, EEA.VDATE2, EEA.MDATE2, EEA.EXC_FXS_TERM_TYPE, EEA.PAY_TYPE, EEA.ASSET_TYPE_10, EEA.ASSET_TYPE_11, EEA.DEAL_MODE FROM ETR_ENTRUST EE LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.ENTRUST_ID = EEA.ENTRUST_ID where EE.FINPROD_TYPE2 IN (#{FINPROD_TYPE2_F10,jdbcType=VARCHAR},#{FINPROD_TYPE2_F01,jdbcType=VARCHAR},#{FINPROD_TYPE2_F06,jdbcType=VARCHAR}) AND EE.PRICE_MODEL = #{PRICE_MODEL_PRICE_MODEL,jdbcType=VARCHAR} and EE.PS IN (#{PS_T01},#{PS_T04}) and #{batchDate,jdbcType=DATE} >= EE.VDATE and EE.ENTRUST_STATUS in (#{ENTRUST_STATUS_02,jdbcType=VARCHAR},#{ENTRUST_STATUS_03,jdbcType=VARCHAR},#{ENTRUST_STATUS_08,jdbcType=VARCHAR})
and (
)

